<template>
  <div class="document-editor-shell" @keydown.esc="closeMenus" @keydown.meta.s.prevent="saveNow" @keydown.ctrl.s.prevent="saveNow">
    <header v-if="editorType.id!=='html'" class="editor-bar">
      <button class="back" type="button" @click="emit('back')"><span v-html="icons.arrowLeft" /> Files</button>
      <div class="bar-spacer" />
      <span class="save-chip" :class="saveState"><i />{{ saveLabel }}</span>
      <div class="presence" aria-label="Present collaborators"><span v-for="peer in peers" :key="peer.id" :title="peer.name">{{ peer.kind==='user'?ownerInitial:peer.name.slice(0,1).toUpperCase() }}</span></div>
      <button class="icon-button" type="button" title="History" :aria-pressed="drawer==='history'" @click="toggleDrawer('history')" v-html="icons.history" />
      <button class="icon-button" type="button" title="Share" @click="openShare" v-html="icons.share" />
      <div ref="moreMenu" class="more-wrap"><button class="icon-button" type="button" title="More" :aria-expanded="moreOpen" @click="moreOpen=!moreOpen" v-html="icons.more" /><div v-if="moreOpen" class="more-menu"><button type="button" @click="moreOpen=false;toggleDrawer('links')">Links</button></div></div>
    </header>

    <div v-if="loading" class="editor-state">Loading document…</div>
    <div v-else-if="loadError" class="editor-state error">{{ loadError }} <button type="button" @click="load()">Retry</button></div>
    <template v-else>
      <main :class="editorType.id==='html'?'html-sheet':'paper-sheet'" :style="editorType.id==='html'?undefined:{maxWidth:`${pageWidth}px`}">
        <template v-if="editorType.id!=='html'">
          <div v-for="side in pageEdges" :key="side" :class="['page-edge',side,{dragging:resizingSide===side}]" role="separator" aria-orientation="vertical" :aria-valuenow="pageWidth" aria-label="Page width" title="Drag to resize the page · double-click to reset" @pointerdown.prevent="startPageResize($event,side)" @dblclick="resetPageWidth" />
          <div class="cover" />
          <h1><input v-if="editingTitle" ref="titleInput" v-model="titleDraft" class="title-input" aria-label="Document title" :readonly="renaming" @keydown.enter.prevent="commitTitle" @keydown.esc.stop.prevent="cancelTitle" @blur="commitTitle"><button v-else type="button" class="title-button" :disabled="readOnly||renaming" title="Rename document" @click="editTitle">{{ title }}</button></h1>
          <p v-if="renameError" class="rename-error" role="alert">{{ renameError }}</p>
          <div class="properties">
            <span class="property">{{ editorType.label }} <b>{{ fileName }}</b></span>
            <button v-for="(value,key) in properties" :key="key" type="button" class="property" :disabled="readOnly" @click="area?.revealProperties?.()">{{ key }} <b>{{ value }}</b></button>
            <button v-if="editorType.id==='markdown'&&!readOnly" type="button" class="property" @click="area?.addProperty?.()">＋ Property</button>
            <span v-if="readOnly" class="property readonly">Read only</span>
          </div>
        </template>
        <component :is="editorType.component" ref="area" v-model="content" :read-only="readOnly" :live="liveBinding" :file-name="fileName" :save-state="saveState" :peers="htmlPeers" :on-back="htmlBack" :on-rename="renameHtml" :on-history="htmlHistory" :on-share="openShare" :on-save="saveNow" @update:model-value="queueSave" @insert-menu="openInsertMenu" />
        <div v-if="slashOpen" ref="insertMenu" class="slash-menu" role="menu" tabindex="-1" aria-label="Insert block" @keydown="navigateMenu" :style="{left:`${menuPoint.x}px`,top:`${menuPoint.y}px`}">
          <section v-for="section in menuSections" :key="section.label"><h2>{{ section.label }}</h2><button v-for="entry in section.entries" :key="entry.label" type="button" role="menuitem" :disabled="entry.disabled" @click="insertMarkdown(entry.text)"><span v-html="entry.icon" /><div><b>{{ entry.label }}</b><small>{{ entry.description }}</small></div></button></section>
        </div>
      </main>
      <aside v-if="drawer" class="drawer">
        <div class="drawer-heading"><h2>{{ drawer==='history'?'History':'Links' }}</h2><button type="button" aria-label="Close drawer" @click="drawer=null">×</button></div>
        <template v-if="drawer==='history'"><p v-if="drawerLoading">Loading versions…</p><article v-for="version in versions" :key="version.id"><b>{{ version.versionNumber ? `v${version.versionNumber}` : shortVersion(version.id) }}</b><span>· {{ versionAuthor(version) }}</span><small>{{ formatDate(version.created_at) }}<template v-if="version.message"> · {{ version.message }}</template></small></article><p v-if="!drawerLoading&&!versions.length">No earlier versions.</p></template>
        <template v-else><p v-if="drawerLoading">Loading links…</p><article v-for="link in links" :key="link.id"><b>{{ link.path.split('/').at(-1) }}</b><span>{{ link.kind.replace('_',' ') }}</span><small>{{ link.direction }}</small></article><p v-if="!drawerLoading&&!links.length">No links yet.</p></template>
      </aside>
      <ShareSheet v-if="shareTarget" :data-source="dataSource" :target="shareTarget" @close="shareTarget=null" />
      <p v-if="shareError" class="rename-error" role="alert">{{ shareError }}</p>
      <div v-if="conflict" class="conflict-banner" role="alert"><b>This file changed elsewhere.</b><span>Your text is still here.</span><button type="button" @click="reloadLatest">Reload latest</button><button type="button" class="primary" @click="keepMine">Keep mine</button></div>
      <div v-else-if="saveError" class="conflict-banner error" role="alert"><b>Couldn't save.</b><span>{{ saveError }}</span><button type="button" @click="saveNow">Try again</button></div>
    </template>
  </div>
</template>
<script setup lang="ts">
import { computed, nextTick, markRaw, onBeforeUnmount, onMounted, ref, shallowRef, watch } from 'vue';
import type { EditorCollaboration } from './codeMirror';
import { LiveDocument } from './liveDocument';
import ShareSheet from '../ShareSheet.vue';
import { editorTypeForPath } from './registry';
import type { FilesDataSource, FilesDetail, FilesItem, FilesSnapshot, FilesVersion } from '../types';

// Page width: drag either edge of the paper sheet. One width for every
// document, remembered across launches.
const PAGE_WIDTH_KEY='sulla.filesEditor.pageWidth', DEFAULT_PAGE_WIDTH=820, MIN_PAGE_WIDTH=520;
const maxPageWidth=()=>Math.max(MIN_PAGE_WIDTH,window.innerWidth-48);
const clampPageWidth=(value:number)=>Math.round(Math.min(maxPageWidth(),Math.max(MIN_PAGE_WIDTH,value)));
const pageWidth=ref(clampPageWidth(Number(localStorage.getItem(PAGE_WIDTH_KEY))||DEFAULT_PAGE_WIDTH));
const resizingSide=ref<'left'|'right'|null>(null);
const pageEdges=['left','right'] as const;
function savePageWidth(){localStorage.setItem(PAGE_WIDTH_KEY,String(pageWidth.value))}
function startPageResize(event:PointerEvent,side:'left'|'right'){
  const startX=event.clientX, startWidth=pageWidth.value, handle=event.currentTarget as HTMLElement;
  resizingSide.value=side; handle.setPointerCapture(event.pointerId);
  // The sheet is centred, so each pixel dragged grows it by two.
  const move=(e:PointerEvent)=>{const dx=e.clientX-startX;pageWidth.value=clampPageWidth(startWidth+(side==='right'?dx:-dx)*2)};
  const end=()=>{resizingSide.value=null;handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end);savePageWidth()};
  handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end);
}
function resetPageWidth(){pageWidth.value=clampPageWidth(DEFAULT_PAGE_WIDTH);savePageWidth()}
// Another open editor window or tab changed the width.
function onPageWidthStorage(event:StorageEvent){if(event.key===PAGE_WIDTH_KEY&&event.newValue)pageWidth.value=clampPageWidth(Number(event.newValue)||DEFAULT_PAGE_WIDTH)}
function onWindowResize(){pageWidth.value=clampPageWidth(Number(localStorage.getItem(PAGE_WIDTH_KEY))||DEFAULT_PAGE_WIDTH)}
onMounted(()=>{window.addEventListener('storage',onPageWidthStorage);window.addEventListener('resize',onWindowResize)});
onBeforeUnmount(()=>{window.removeEventListener('storage',onPageWidthStorage);window.removeEventListener('resize',onWindowResize)});
const props=defineProps<{ dataSource:FilesDataSource; item:FilesItem; collectionId?:string; files?:FilesItem[] }>();
const emit=defineEmits<{ back:[]; saved:[item:FilesItem] }>();
// Yjs objects must never be wrapped in Vue proxies.
const liveBinding=shallowRef<EditorCollaboration|null>(null);
const liveState=ref<'live'|'syncing'|'offline'|null>(null),peers=ref<{id:string;name:string;kind:string}[]>([]);
let live:LiveDocument|undefined;let loadGeneration=0;
const area=ref<{revealProperties?:()=>void;insertBlock?:(text:string)=>void;addProperty?:()=>void}|null>(null);
const titleInput=ref<HTMLInputElement>(),editingTitle=ref(false),titleDraft=ref(''),renameError=ref(''),renaming=ref(false);
const insertMenu=ref<HTMLElement>(),moreMenu=ref<HTMLElement>(),moreOpen=ref(false),menuPoint=ref({x:0,y:0}),collection=ref<FilesSnapshot['collection']>();
const shareTarget=ref<InstanceType<typeof ShareSheet>['$props']['target']|null>(null),shareError=ref('');
const loading=ref(true), loadError=ref(''), content=ref(''), baseVersionId=ref(''), saveState=ref<'saved'|'saving'|'merged'|'conflict'|'error'>('saved'), saveError=ref(''), conflict=ref<{currentVersionId:string}|null>(null), slashOpen=ref(false), drawer=ref<'history'|'links'|null>(null), drawerLoading=ref(false), versions=ref<FilesVersion[]>([]), detail=ref<FilesDetail|null>(null); let timer:ReturnType<typeof setTimeout>|undefined;
const extension=computed(()=>/\.sulla\.md$|\.(?:sulla|md|txt|html|htm)$/i.exec(fileName.value)?.[0]??'');
const editorType=computed(()=>editorTypeForPath(props.item.path)!); const fileName=computed(()=>props.item.path.split('/').at(-1)??props.item.path); const title=computed(()=>fileName.value.slice(0,fileName.value.length-extension.value.length)); const properties=computed(()=>editorType.value.parse(content.value).properties); const readOnly=computed(()=>(detail.value?.capabilities??props.item.capabilities)?.canEdit===false); const ownerInitial=computed(()=>(props.item.ownerDisplayName||'J').trim()[0]?.toUpperCase()||'J'); const links=computed(()=>detail.value?.links??[]);
const htmlPeers=computed(()=>peers.value.map(peer=>({id:peer.id,name:peer.name,kind:peer.kind==='user'?'user' as const:'agent' as const})));
const saveLabel=computed(()=>liveState.value?(liveState.value==='live'?'Live':liveState.value==='syncing'?'Syncing…':'Offline'):saveState.value==='saving'?'Saving…':saveState.value==='merged'?`Merged · ${shortVersion(baseVersionId.value)}`:saveState.value==='conflict'?'Conflict':saveState.value==='error'?'Not saved':`Saved · ${shortVersion(baseVersionId.value)}`);
const icons={share:'<svg viewBox="0 0 24 24"><path d="M12 16V3m-4 4 4-4 4 4M5 12v8h14v-8"/></svg>',arrowLeft:'<svg viewBox="0 0 24 24"><path d="m15 18-6-6 6-6"/></svg>',history:'<svg viewBox="0 0 24 24"><path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5M12 7v5l3 2"/></svg>',link:'<svg viewBox="0 0 24 24"><path d="M10 13a5 5 0 0 0 7.5.5l2-2a5 5 0 0 0-7-7l-1.1 1.1M14 11a5 5 0 0 0-7.5-.5l-2 2a5 5 0 0 0 7 7l1.1-1.1"/></svg>',more:'<svg viewBox="0 0 24 24"><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></svg>',heading:'<svg viewBox="0 0 24 24"><path d="M5 4v16M19 4v16M5 12h14"/></svg>',list:'<svg viewBox="0 0 24 24"><path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/></svg>',check:'<svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="3"/><path d="m7 12 3 3 7-7"/></svg>',table:'<svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 10h18M9 4v16"/></svg>',toggle:'<svg viewBox="0 0 24 24"><path d="m9 18 6-6-6-6"/></svg>'};
const menuSections=[
 {label:'Components',entries:[{label:'Chart',description:'Bar, line or pie — data kept in the file',icon:icons.table,text:'',disabled:true},{label:'Checklist',description:'Tasks with owners',icon:icons.check,text:'- [ ] Task\n',disabled:false},{label:'Table',description:'Rows and columns',icon:icons.table,text:'| Column | Column |\n| --- | --- |\n|  |  |\n',disabled:false}]},
 {label:'Layout',entries:[{label:'Heading',description:'Section title',icon:icons.heading,text:'## Heading\n',disabled:false},{label:'List',description:'Bulleted list',icon:icons.list,text:'- List item\n',disabled:false},{label:'Toggle',description:'Collapsible section',icon:icons.toggle,text:'<details>\n<summary>Toggle</summary>\n\n</details>\n',disabled:false}]},
 {label:'Link',entries:[{label:'Link',description:'Link to a page or file',icon:icons.link,text:'[link](https://)',disabled:false}]},
];
function shortVersion(value:string){return value?`v${value.replace(/^version-/,'').slice(0,8)}`:'v—'}
function formatDate(value:string){const date=new Date(value);if(!Number.isFinite(date.getTime()))return '';const minutes=Math.max(0,Math.floor((Date.now()-date.getTime())/60000));if(minutes<1)return 'just now';if(minutes<60)return `${minutes} min ago`;if(minutes<1440)return `${Math.floor(minutes/60)} hr ago`;const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);if(date.toDateString()===yesterday.toDateString())return 'yesterday';return date.toLocaleDateString()}
function versionAuthor(version:FilesVersion){if(version.created_by_type==='agent')return peers.value.find(peer=>peer.id===version.created_by_id)?.name||'Sulla';if(version.created_by_type==='user'){if(version.created_by_id===collection.value?.ownerUserId||(props.item.createdByType==='user'&&version.created_by_id===props.item.createdById))return props.item.ownerDisplayName||'Owner';return peers.value.find(peer=>peer.id===version.created_by_id)?.name||'User'}return 'Sulla'}
async function loadCollection(){const snapshot=await props.dataSource.load();if(props.collectionId&&snapshot.collection.id!==props.collectionId)throw new Error('The document collection is not selected. Reopen this document from Files.');collection.value=snapshot.collection;return snapshot.collection}
function htmlBack(){emit('back')}
function htmlHistory(){void toggleDrawer('history')}
async function renameHtml(name:string){const suffix=extension.value;titleDraft.value=name.endsWith(suffix)?name.slice(0,-suffix.length):name;editingTitle.value=true;await commitTitle()}
async function editTitle(){if(readOnly.value||renaming.value)return;renameError.value='';titleDraft.value=title.value;editingTitle.value=true;await nextTick();titleInput.value?.focus();titleInput.value?.select()}
function cancelTitle(){editingTitle.value=false;titleDraft.value=title.value}
async function commitTitle(){if(!editingTitle.value||renaming.value)return;if(readOnly.value){cancelTitle();return}const name=titleDraft.value.trim();if(!name||name.includes('/')||name==='.'||name==='..'){renameError.value='Enter a name without slashes; the name cannot be empty, . or ..';cancelTitle();return}if(name===title.value){cancelTitle();return}renaming.value=true;renameError.value='';const item=props.item;try{const collectionId=props.collectionId||(await loadCollection()).id;const parent=item.path.slice(0,item.path.lastIndexOf('/')+1);const path=parent+name+extension.value;await props.dataSource.operate('move',collectionId,[{fileId:item.id,targetPath:path}]);if(props.item.id===item.id)emit('saved',{...props.item,path});editingTitle.value=false}catch(cause){renameError.value=`Couldn't rename: ${cause instanceof Error?cause.message:String(cause)}`;cancelTitle()}finally{renaming.value=false}}
async function openShare(){shareError.value='';const item=props.item;try{const info=await loadCollection();if(props.item.id!==item.id)return;shareTarget.value={id:item.id,name:item.path.split('/').at(-1)||item.path,folder:false,path:item.path,collectionId:props.collectionId||info.id,orgId:info.orgId,ownerUserId:info.ownerUserId,assetKind:'file'}}catch(cause){shareError.value=`Couldn't open sharing: ${cause instanceof Error?cause.message:String(cause)}`}}
async function openInsertMenu(point:{x:number;y:number}){if(readOnly.value||editorType.value.id!=='markdown')return;slashOpen.value=true;menuPoint.value=point;await nextTick();const rect=insertMenu.value?.getBoundingClientRect();menuPoint.value={x:Math.max(8,Math.min(point.x,window.innerWidth-(rect?.width??320)-8)),y:Math.max(8,Math.min(point.y,window.innerHeight-(rect?.height??480)-8))};insertMenu.value?.focus({preventScroll:true})}
function navigateMenu(event:KeyboardEvent){if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return;event.preventDefault();const buttons=Array.from(insertMenu.value?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')??[]);if(!buttons.length)return;const index=buttons.indexOf(document.activeElement as HTMLButtonElement);const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:event.key==='ArrowDown'?(index+1)%buttons.length:(index<0?buttons.length-1:(index-1+buttons.length)%buttons.length);buttons[next]?.focus()}
function closeMenus(){slashOpen.value=false;moreOpen.value=false}
function outsideClick(event:PointerEvent){const target=event.target as Node;if(!insertMenu.value?.contains(target))slashOpen.value=false;if(!moreMenu.value?.contains(target))moreOpen.value=false}
async function load(versionId?:string){const generation=++loadGeneration;const fileId=props.item.id;const previous=live;live=undefined;liveBinding.value=null;liveState.value=null;peers.value=[];await previous?.close();loading.value=true;loadError.value='';clearTimeout(timer);pendingSave=false;try{const metadata=await props.dataSource.detail(fileId);if(generation!==loadGeneration)return;const loadedVersion=versionId||metadata.version?.id||props.item.currentVersionId;const preview=await props.dataSource.preview(fileId,loadedVersion);if(generation!==loadGeneration)return;content.value=new TextDecoder().decode(preview.data);baseVersionId.value=loadedVersion;detail.value=metadata;saveState.value='saved';conflict.value=null;
if(!versionId&&props.dataSource.openLive){const session=new LiveDocument(props.dataSource,fileId,value=>{if(generation===loadGeneration)content.value=value;},value=>{if(generation===loadGeneration)liveState.value=value;},value=>{if(generation===loadGeneration)peers.value=value;});live=session;try{await session.start();if(generation===loadGeneration&&live===session)liveBinding.value=markRaw({ytext:session.ytext,undoManager:session.undoManager});}catch{await session.close();if(live===session){live=undefined;liveBinding.value=null;liveState.value=null;}}}
}catch(cause){loadError.value=cause instanceof Error?cause.message:String(cause)}finally{if(generation===loadGeneration)loading.value=false}}
function queueSave(){if(readOnly.value)return;if(live){live.edit(content.value);return;}saveState.value='saving';conflict.value=null;saveError.value='';clearTimeout(timer);timer=setTimeout(saveNow,850)}
// Single-range diff: enough to tell whether two edits touch the same span.
function rangeDiff(from:string,to:string){let start=0;while(start<from.length&&start<to.length&&from[start]===to[start])start++;let end=0;while(end<from.length-start&&end<to.length-start&&from[from.length-1-end]===to[to.length-1-end])end++;return{from:start,to:from.length-end,insert:to.slice(start,to.length-end)}}
// Applies the server's merged changes on top of text typed while the save was in flight; null when both touched the same span.
function rebase(sent:string,merged:string,local:string):string|null{if(local===sent)return merged;const theirs=rangeDiff(sent,merged),mine=rangeDiff(sent,local);if(theirs.to<=mine.from)return local.slice(0,theirs.from)+theirs.insert+local.slice(theirs.to);if(theirs.from>=mine.to){const shift=mine.insert.length-(mine.to-mine.from);return local.slice(0,theirs.from+shift)+theirs.insert+local.slice(theirs.to+shift)}return null}
let saving=false,pendingSave=false;
async function saveNow(){if(live){live.edit(content.value);return;}clearTimeout(timer);if(readOnly.value||loading.value)return;if(saving){pendingSave=true;return}saving=true;pendingSave=false;saveState.value='saving';saveError.value='';const sent=content.value;try{const result=await props.dataSource.saveContent({fileId:props.item.id,baseVersionId:baseVersionId.value,content:editorType.value.serialize({content:sent,properties:editorType.value.parse(sent).properties})});if(result.status==='merged'){const next=rebase(sent,result.content,content.value);if(next===null){conflict.value={currentVersionId:result.versionId};saveState.value='conflict';return}baseVersionId.value=result.versionId;if(next!==content.value)content.value=next;if(next!==result.content)pendingSave=true}else{baseVersionId.value=result.versionId;if(content.value!==sent)pendingSave=true}saveState.value=pendingSave?'saving':result.status;conflict.value=null;emit('saved',{...props.item,currentVersionId:result.versionId,updatedAt:new Date().toISOString()})}catch(cause){const error=cause as Error&{code?:string;currentVersionId?:string;status?:number};if(error.code==='VERSION_CONFLICT'||error.status===409){conflict.value={currentVersionId:error.currentVersionId||''};saveState.value='conflict'}else{saveError.value=error.message||String(cause);saveState.value='error'}}finally{saving=false;if(pendingSave&&!conflict.value)void saveNow()}}
async function reloadLatest(){const versionId=conflict.value?.currentVersionId||props.item.currentVersionId;await load(versionId)}
async function keepMine(){if(conflict.value?.currentVersionId)baseVersionId.value=conflict.value.currentVersionId;conflict.value=null;await saveNow()}
function insertMarkdown(value:string){area.value?.insertBlock?.(value);slashOpen.value=false}
async function toggleDrawer(value:'history'|'links'){drawer.value=drawer.value===value?null:value;if(!drawer.value)return;drawerLoading.value=true;try{if(value==='history')versions.value=await props.dataSource.history(props.item.id,baseVersionId.value);else detail.value=await props.dataSource.detail(props.item.id)}finally{drawerLoading.value=false}}
watch(()=>props.item.id,()=>{cancelTitle();closeMenus();renameError.value='';shareError.value='';shareTarget.value=null;drawer.value=null;void load();void loadCollection().catch(()=>{})});onMounted(()=>{void load();void loadCollection().catch(()=>{});document.addEventListener('pointerdown',outsideClick)});onBeforeUnmount(()=>{document.removeEventListener('pointerdown',outsideClick);++loadGeneration;liveBinding.value=null;void live?.close();clearTimeout(timer);if(saveState.value==='saving'&&!readOnly.value)void saveNow()});
</script>
